    def _mkid(prefix):
        ts = datetime.datetime.utcnow()
        return f"jmg_{prefix}_{ts.strftime('%y%m%d%H%M%S')}{os.urandom(8).hex()}".lower()

    def _audit(client_id, api_key_id, status_code, payload, job_id_val=None):
        logs = _load("request_audit_log.json")
        entry = {
            "id": _mkid("req"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": "listGeneratedImages",
            "request_payload": payload if isinstance(payload, dict) else {},
