            "ip_address": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(entry)
        _save("request_audit_log.json", logs)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _audit(None, None, 401, {"api_key": api_key, "job_id": job_id, "status": status, "limit": limit, "cursor": cursor})
        return _err("UNAUTHORIZED", "API key is missing, invalid, revoked, or expired.")
    if not isinstance(job_id, str) or not job_id.strip():
        _audit(None, None, 400, {"api_key": api_key, "job_id": job_id, "status": status, "limit": limit, "cursor": cursor})
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string.")
    if status is not None and status not in ("available", "deleted"):
        _audit(None, None, 400, {"api_key": api_key, "job_id": job_id, "status": status, "limit": limit, "cursor": cursor})
        return _err("VALIDATION_ERROR", "status must be one of: available, deleted.")
    if limit is None:
        limit_val = 100
    else:
        if not isinstance(limit, int):
            _audit(None, None, 400, {"api_key": api_key, "job_id": job_id, "status": status, "limit": limit, "cursor": cursor})
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        # Relaxed to accept caller's value; clamp rather than error to avoid over-strict rejection.
        limit_val = max(1, min(1000, limit))

    keys = _load("api_keys.json")
    clients = _load("api_clients.json")
    jobs = _load("image_generation_jobs.json")
    images = _load("generated_images.json")

    # Authenticate by matching api_keys.id or key_prefix (client-visible)
    api_key_s = api_key.strip()
    key_row = None
    for k in keys:
        if isinstance(k, dict) and (k.get("id") == api_key_s or k.get("key_prefix") == api_key_s):
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _audit(None, key_row.get("id") if isinstance(key_row, dict) else None, 401, {"api_key": api_key_s, "job_id": job_id, "status": status, "limit": limit, "cursor": cursor})
        return _err("UNAUTHORIZED", "API key is missing, invalid, revoked, or expired.")

    client_id = key_row.get("client_id")
    client_row = None
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            client_row = c
            break
    if not client_row:
        _audit(None, key_row.get("id"), 401, {"api_key": api_key_s, "job_id": job_id, "status": status, "limit": limit, "cursor": cursor})
        return _err("UNAUTHORIZED", "API key is missing, invalid, revoked, or expired.")
    if client_row.get("status") != "active":
        _audit(client_row.get("id"), key_row.get("id"), 403, {"api_key": api_key_s, "job_id": job_id, "status": status, "limit": limit, "cursor": cursor})
        return _err("UNAUTHORIZED", "Owning client is not active.", rule="api_clients.status must be 'active'")

    # Find job and enforce ownership
    job_row = None
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            job_row = j
            break
    if not job_row or job_row.get("client_id") != client_row.get("id"):
        _audit(client_row.get("id"), key_row.get("id"), 404, {"api_key": api_key_s, "job_id": job_id, "status": status, "limit": limit, "cursor": cursor})
        return _err("NOT_FOUND", "Job not found.")

    # Cursor: accept any opaque string; if it matches an image id, start after it; if not, start from beginning.
    start_after_id = cursor if isinstance(cursor, str) and cursor.strip() else None

    # Filter and order
    filtered = []
    for im in images:
        if not isinstance(im, dict):
            continue
        if im.get("job_id") != job_id:
            continue
        if status is not None and im.get("status") != status:
            continue
        filtered.append(im)
    filtered.sort(key=lambda r: (r.get("index") if isinstance(r.get("index"), int) else 10**9, r.get("id") or ""))

    # Apply cursor
    start_idx = 0
    if start_after_id:
        for i, im in enumerate(filtered):
            if im.get("id") == start_after_id:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + limit_val]
    has_more = start_idx + limit_val < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    # Ensure contiguity in returned results: return from the smallest index present in this page, but only contiguous sequence.
    # This keeps results contiguous even if internal storage has gaps.
    if page:
        by_index = {im.get("index"): im for im in page if isinstance(im.get("index"), int)}
        min_index = min(by_index.keys()) if by_index else None
        if min_index is not None:
            contiguous = []
            cur = min_index
            while cur in by_index and len(contiguous) < len(page):
                contiguous.append(by_index[cur])
                cur += 1
            # If contiguity trimming removed items, adjust has_more/next_cursor conservatively.
            if contiguous:
                page = contiguous
                # next_cursor should reflect last returned id
                next_cursor = page[-1].get("id") if has_more else None

    # Update key usage timestamp on successful use
    key_row["last_used_at"] = _utc()
    key_row["updated_at"] = _utc()
    _save("api_keys.json", keys)

    _audit(client_row.get("id"), key_row.get("id"), 200, {"api_key": api_key_s, "job_id": job_id, "status": status, "limit": limit, "cursor": cursor}, job_id_val=job_id)
    return {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit_val,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        },
    }

def cancelImageGenerationJob(api_key, job_id, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0036000" if __import__("os").path.isdir("./environment_mix/0036000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _mkid(prefix):
        # Generate ids consistent with existing examples: jmg_req_01...
        # We implement a stable-ish, sortable id with time component; not cryptographic.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        rand = int.from_bytes(os.urandom(8), "big")
        v = (ts << 64) | rand
        out = []
        for _ in range(26):
            out.append(alphabet[v & 31])
            v >>= 5
        out = "".join(reversed(out))
        return f"jmg_{prefix}_{out}"

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _audit(client_id, api_key_id, status_code, payload, job_id_val=None):
        logs = _load("request_audit_log.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": _mkid("req"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": "cancelImageGenerationJob",
            "request_payload": payload if isinstance(payload, dict) else {},
            "response_status_code": int(status_code),
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "job_id": job_id_val,
            "ip_address": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(entry)
        _save("request_audit_log.json", logs)

    def _resolve_auth(api_key_value):
        # IMPORTANT: Never compare against key_hash (plaintext doesn't exist here).
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, None, _err("UNAUTHORIZED", "API key is required.", rule="api_key required", field="api_key")
        api_key_s = api_key_value.strip()

        keys = _load("api_keys.json")
        clients = _load("api_clients.json")
        if not isinstance(keys, list):
            keys = []
        if not isinstance(clients, list):
            clients = []

        client_by_id = {c.get("id"): c for c in clients if isinstance(c, dict) and isinstance(c.get("id"), str)}
        nowp = datetime.datetime.utcnow()

        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") != api_key_s and k.get("key_prefix") != api_key_s:
                continue
            # status check
            st = k.get("status")
            if st != "active":
                continue
            # expiration check
            exp = _parse_ts(k.get("expires_at"))
            if exp and exp <= nowp:
                continue
            cli = client_by_id.get(k.get("client_id"))
            if not cli or cli.get("status") != "active":
                continue
            candidates.append((k, cli))

        if not candidates:
            return None, None, _err(
                "UNAUTHORIZED",
                "API key is missing, invalid, revoked/expired, or its client is not active.",
                rule="key must be active and belong to an active client",
            )

        # If multiple match (possible for prefix), choose the most recently updated key.
        def _upd(x):
            k = x[0]
            d = _parse_ts(k.get("updated_at")) or _parse_ts(k.get("created_at")) or datetime.datetime(1970, 1, 1)
            return d
        candidates.sort(key=_upd, reverse=True)
        key_row, client_row = candidates[0]

        # Update last_used_at for successful auth (realistic behavior)
        key_row["last_used_at"] = now
        key_row["updated_at"] = now
        # persist key update
        for i, kk in enumerate(keys):
            if isinstance(kk, dict) and kk.get("id") == key_row.get("id"):
                keys[i] = key_row
                break
        _save("api_keys.json", keys)

        return client_row, key_row, None

    def _enforce_rate_limit(client_id):
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        cli = None
        for c in clients:
            if isinstance(c, dict) and c.get("id") == client_id:
                cli = c
                break
        if not cli:
            return _err("UNAUTHORIZED", "Authenticated client not found.", rule="client must exist")

        rpm = cli.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            return _err("VALIDATION_ERROR", "Client rate limit configuration invalid.", rule="rate_limit_rpm range")

        logs = _load("request_audit_log.json")
        if not isinstance(logs, list):
            logs = []
        window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts and ts >= window_start:
                count += 1
        if count >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.", rule="rate_limit_rpm per minute")
        return None

    # Validate inputs
    if not isinstance(job_id, str) or not job_id.strip():
        _audit(None, None, 400, {"api_key": api_key, "job_id": job_id, "reason": reason})
        return _err("VALIDATION_ERROR", "job_id is required.", field="job_id", rule="required")
    if reason is not None and not isinstance(reason, str):
        _audit(None, None, 400, {"api_key": api_key, "job_id": job_id, "reason": reason})
        return _err("VALIDATION_ERROR", "reason must be a string if provided.", field="reason", rule="type string")

    # Auth
    client_row, key_row, auth_err = _resolve_auth(api_key)
    if auth_err:
        _audit(None, None, 401, {"api_key": api_key, "job_id": job_id, "reason": reason})
        return auth_err

    # Rate limit (observable, applied to all tools)
    rl_err = _enforce_rate_limit(client_row.get("id"))
    if rl_err:
        _audit(client_row.get("id"), key_row.get("id"), 429, {"api_key": api_key, "job_id": job_id, "reason": reason})
        return rl_err

    # Find job
    jobs = _load("image_generation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    job = None
    job_idx = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id:
            job = j
            job_idx = i
            break

    if not job or job.get("client_id") != client_row.get("id"):
        _audit(client_row.get("id"), key_row.get("id"), 404, {"api_key": api_key, "job_id": job_id, "reason": reason})
        return _err("NOT_FOUND", "Job not found.", rule="job must exist and be owned by authenticated client")

    # Enforce lifecycle transitions
    st = job.get("status")
    if st in ("succeeded", "failed", "cancelled"):
        _audit(client_row.get("id"), key_row.get("id"), 409, {"api_key": api_key, "job_id": job_id, "reason": reason}, job_id_val=job_id)
        return _err("CONFLICT", f"Job cannot be cancelled from status '{st}'.", rule="terminal jobs are immutable")
    if st not in ("queued", "running"):
        _audit(client_row.get("id"), key_row.get("id"), 409, {"api_key": api_key, "job_id": job_id, "reason": reason}, job_id_val=job_id)
        return _err("INVALID_TRANSITION", f"Job cannot be cancelled from status '{st}'.", rule="only queued/running may transition to cancelled")

    # Mutate
    job["status"] = "cancelled"
    job["finished_at"] = now
    job["updated_at"] = now
    # Optionally attach cancellation reason into request_payload metadata without altering tool schema
    if isinstance(reason, str) and reason.strip():
        rp = job.get("request_payload")
        if not isinstance(rp, dict):
            rp = {}
        meta = rp.get("_cancellation")
        if not isinstance(meta, dict):
            meta = {}
        meta["reason"] = reason.strip()
        meta["requested_at"] = now
        meta["api_key_id"] = key_row.get("id")
        rp["_cancellation"] = meta
        job["request_payload"] = rp

    jobs[job_idx] = job
    _save("image_generation_jobs.json", jobs)

    _audit(client_row.get("id"), key_row.get("id"), 200, {"api_key": api_key, "job_id": job_id, "reason": reason}, job_id_val=job_id)
    return {"job": job}

